(function () {
  'use strict';
  var sources = '<details class="evx-sources"><summary>这些推理原则从哪里来？</summary><p>题目与数值均为原创虚构练习，不代表真实研究。下列资料用于理解通用原则。</p><ul><li><a href="https://openstax.org/books/introductory-statistics/pages/1-4-experimental-design-and-ethics" target="_blank" rel="noopener noreferrer">OpenStax：实验设计、对照与随机分配</a></li><li><a href="https://openstax.org/books/psychology-2e/pages/2-3-analyzing-findings" target="_blank" rel="noopener noreferrer">OpenStax：相关与因果</a></li><li><a href="https://www.itl.nist.gov/div898/handbook/eda/section3/eda352.htm" target="_blank" rel="noopener noreferrer">NIST：均值的置信区间与不确定性</a></li><li><a href="https://www.itl.nist.gov/div898/handbook/eda/section3/eda35.htm" target="_blank" rel="noopener noreferrer">NIST：统计显著与实际意义</a></li></ul></details>';
  // The first choice is correct in the source bank; positions are shuffled for every session.
  var bank = [
    {id:'cause',topic:'因果判断',level:'入门',title:'冰饮卖得好，是冰饮让人怕热？',text:'虚构街区记录显示：冰饮销量越高，当天遮阳伞销量也越高。哪种说法最稳妥？',choices:['两者相关；气温可能同时影响两种销量。','喝冰饮会让人更需要遮阳伞。','买遮阳伞一定会让人购买冰饮。'],hint:'先找有没有一个因素，同时推动两件事。',explain:'两种销量一起变化，只能直接支持相关。天气炎热可能同时增加两者的需求，这叫潜在混杂因素。记录本身没有随机干预，也无法排除其他解释，因此不能认定其中一个造成另一个。'},
    {id:'units',topic:'独立重复',level:'进阶',title:'测了 30 次，就有 30 个样本吗？',text:'虚构实验把同一锅果酱分装成 3 杯，每杯读数 10 次。研究者想比较“不同批次”的糖度波动。下一步最有帮助的是？',choices:['独立制作多锅果酱，再测各锅糖度。','对同一杯再读 100 次。','把现有 30 个读数都称作独立生产批次。'],hint:'想研究锅与锅的差异，就要真的有不同的锅。',explain:'重复读数能帮助了解测量稳定性，却不能替代独立生产批次。3 杯来自同一锅，仍共享这锅的原料和加工经历。要评价批次差异，需要多次独立制作，并把批次与技术重复分开报告。'},
    {id:'null',topic:'阴性结果',level:'进阶',title:'没有检出差异，等于完全相同？',text:'一项虚构的小型饼干包装实验未检出两种包装的脆度差异。报告没有给出差异范围。最合理的结论是？',choices:['本次未检出差异；仍需了解样本量与估计的不确定性。','已证明两种包装在任何条件下完全相同。','未检出差异说明实验数据一定有错。'],hint:'“还没看清差异”和“证明没有差异”是两种结论。',explain:'未达到统计显著，可能来自差异很小，也可能来自数据波动大或样本量不足。不能据此断言完全相同。若要支持两种包装足够接近，应预先定义可接受的差异，并采用适当的等效性设计与区间分析。'},
    {id:'control',topic:'对照设计',level:'入门',title:'面包变软，功劳该给谁？',text:'虚构实验中，新配方同时增加糖量并缩短烘烤时间，面包更软了。想判断“加糖”的作用，应优先怎样比较？',choices:['保持烘烤等条件一致，只改变糖量，并安排独立重复。','把糖量和烘烤时间一起增加。','只询问研发者更喜欢哪种面包。'],hint:'让比较中的主要区别，正好是你想检验的因素。',explain:'糖量和烘烤时间同时改变，结果无法归因给某一个因素。保持其他条件一致，并通过随机分配和独立重复减少偏差，才能更清楚地估计糖量的作用。感官偏好也可以研究，但它是另一个问题。'},
    {id:'axis',topic:'图表识读',level:'入门',title:'看起来翻倍，真的翻倍了吗？',text:'虚构海报用从 9 开始的纵轴画柱状图，第二根柱子看起来是第一根的两倍高。原始均值如下。实际变化是多少？',table:{caption:'两组糖度均值（虚构，单位：°Bx）',head:['组别','糖度'],rows:[['A','10'],['B','11']]},choices:['B 比 A 高 10%；截断纵轴放大了视觉差异。','B 比 A 高 100%，因为柱子看起来高一倍。','B 比 A 低 10%。'],hint:'先算 (11 − 10) ÷ 10，再看图形。',explain:'从 10 到 11，增加 1，以原来的 10 为基数，增幅为 10%。纵轴从 9 起画时，可见柱长分别是 1 和 2，容易造成翻倍的印象。看图时应核对坐标轴、单位和原始数值。'},
    {id:'percent',topic:'百分比',level:'入门',title:'“减少 50%”究竟少多少？',text:'虚构生产线在相同检查标准下，记录了改造前后不合格包装数量。下列哪句话计算正确？',table:{caption:'包装检查记录（虚构）',head:['阶段','检查数','不合格数'],rows:[['改造前','100','4'],['改造后','100','2']]},choices:['不合格率从 4% 到 2%，下降 2 个百分点，相对下降 50%。','不合格率下降了 50 个百分点。','改造后不合格率是 50%。'],hint:'百分点算两个率的差；相对降幅还要除以原来的率。',explain:'原不合格率为 4/100，新不合格率为 2/100。绝对差是 2 个百分点，相对降幅是 (4% − 2%)/4% = 50%。这份前后记录能描述变化，但单凭它还不能排除原料、人员等同期变化的影响。'},
    {id:'model',topic:'证据来源',level:'入门',title:'电脑预测，也能写成实测吗？',text:'虚构模型根据旧数据预测：某烘干条件下，含水率会达到 8%。这次尚未做烘干实验。怎样记录最准确？',choices:['模型预测含水率为 8%，尚待独立实验验证。','本次实验测得含水率为 8%。','既然模型给了数字，就无需说明来源。'],hint:'数字的来源，决定了它能支持哪种结论。',explain:'模型输出是依赖输入数据、假设和适用范围的预测，不能改称本次实验测量。准确记录来源，并用独立数据检验模型，才能判断预测是否适用于新的原料和条件。'},
    {id:'dose',topic:'变量与材料',level:'入门',title:'三个添加量，等于三种原料？',text:'虚构实验将同一瓶纯化果胶分别按 0.1%、0.3%、0.5% 加入饮料，标记为低、中、高组。哪种表述准确？',choices:['这是同一材料的三个添加量组。','这是分离得到的三种不同果胶组分。','添加量不同就能证明分子结构不同。'],hint:'改变加多少，不会自动改变加的是什么。',explain:'这里操纵的是添加量，材料仍来自同一瓶果胶。分离组分需要实际的分离过程和材料表征证据。仅凭低、中、高这样的组名，不能推断纯度、组成或分子结构存在差别。'},
    {id:'selection',topic:'选择偏差',level:'进阶',title:'粉丝都喜欢，所有人都会喜欢？',text:'虚构品牌只邀请自家会员群的 300 人试喝新品，其中 90% 表示喜欢。最稳妥的宣传描述是？',choices:['在本次会员群试喝者中，90% 表示喜欢；不能直接代表所有消费者。','全国 90% 的消费者一定喜欢。','人数达到 300，就自动消除了抽样偏差。'],hint:'先看“找了谁”，再看“找了多少人”。',explain:'会员可能本来就更认同品牌，愿意参与的人也可能与未参与者不同。样本变大可以降低某些随机波动，却不能自动修复抽样方式造成的系统偏差。结果的适用人群需要与招募方式相匹配。'},
    {id:'meaning',topic:'实际意义',level:'进阶',title:'显著，是否就值得改生产线？',text:'虚构大样本实验发现，新工艺使每包产品平均增重 0.01 克，统计检验达到显著。是否立刻采用新工艺？',choices:['还需结合差异大小、不确定性、成本和预先设定的目标。','统计显著就说明经济收益一定很大。','差异小就说明统计结果一定是假的。'],hint:'能否区分差异，与差异是否值得投入，是两个问题。',explain:'统计显著并不直接告诉我们差异有多大或是否有应用价值。大样本可能检测到很小的差别。工艺决策还需考虑实际效应、区间估计、成本、稳定性，以及事先确定的质量要求。'},
    {id:'blind',topic:'盲法与顺序',level:'进阶',title:'先看到“高级款”，评分会改变吗？',text:'虚构试吃中，所有人都先吃写着“高级款”的 A，再吃写着“普通款”的 B，最后给口感评分。怎样改进比较？',choices:['使用随机编码隐藏名称，并平衡或随机安排品尝顺序。','把“高级款”标签印得更大。','要求所有人先吃 A，保证顺序绝对一致即可。'],hint:'标签期待与先后顺序，都可能混进评分。',explain:'知道标签可能产生期待偏差；固定顺序也可能让饥饿、疲劳或前一种味道影响后一种评分。随机编码与随机或平衡顺序可以减少这些影响。仍应同时明确评分标准、招募方式和独立样本数。'},
    {id:'range',topic:'外推边界',level:'进阶',title:'测到 60°C，就能推荐 100°C？',text:'虚构实验只比较了 40、50、60°C 的干燥过程，温度越高用时越短。研究者想宣布“100°C 一定最好”。怎样评价？',choices:['100°C 超出已测试范围，需要新实验并同时评价品质等指标。','趋势向下，就能保证任何更高温度都更好。','只要画出直线，外推就变成了实测。'],hint:'先找结论有没有跨过数据真正覆盖的范围。',explain:'区间内的趋势不能保证在区间外继续成立。更高温度可能出现新的变化，而“最好”还取决于时间、品质、能耗等目标。应把外推明确标为预测，在目标条件下验证，并事先定义评价标准。'}
  ];
  function shuffle(a) { a=a.slice(); for(var i=a.length-1;i>0;i--){var j=Math.floor(Math.random()*(i+1));var t=a[i];a[i]=a[j];a[j]=t;} return a; }
  function tableHTML(t) { return t ? '<div class="evx-table-wrap"><table><caption>'+t.caption+'</caption><thead><tr>'+t.head.map(function(h){return '<th scope="col">'+h+'</th>';}).join('')+'</tr></thead><tbody>'+t.rows.map(function(r){return '<tr>'+r.map(function(v,i){return i===0?'<th scope="row">'+v+'</th>':'<td>'+v+'</td>';}).join('')+'</tr>';}).join('')+'</tbody></table></div>' : ''; }
  window.LabModules=window.LabModules||{};
  window.LabModules.evidence={mount:function(container,options){
    options=options||{}; var round=[],index=0,score=0,answers=[],locked=false,selected=null,finished=false,disposed=false,previous='';
    container.classList.add('evx-host');
    function start(){ var pick=shuffle(bank).slice(0,6); var signature=pick.map(function(q){return q.id;}).sort().join(','); if(signature===previous){var outside=bank.filter(function(q){return !pick.some(function(p){return p.id===q.id;});});pick[5]=shuffle(outside)[0];signature=pick.map(function(q){return q.id;}).sort().join(',');} previous=signature; round=pick.map(function(q){return {q:q,choices:shuffle(q.choices.map(function(text,i){return {text:text,correct:i===0};}))};}); index=0;score=0;answers=[];finished=false;render(); }
    function render(){locked=false;selected=null;var item=round[index],q=item.q;container.innerHTML='<section class="evx-game" aria-label="证据侦探"><header class="evx-header"><span class="evx-eyebrow">EVIDENCE DETECTIVE</span><div class="evx-heading"><h2>证据侦探</h2><span class="evx-count">'+(index+1)+' / 6</span></div><p>先问证据，再下结论。每轮随机抽取 6 案。</p><progress class="evx-progress" max="6" value="'+index+'" aria-label="已完成 '+index+' 题，共 6 题"></progress></header><div class="evx-meta"><span>'+q.topic+'</span><span>'+q.level+'</span><span>虚构练习</span></div><form class="evx-form"><fieldset><legend class="evx-title" tabindex="-1">'+q.title+'</legend><p class="evx-scenario">'+q.text+'</p>'+tableHTML(q.table)+'<div class="evx-choices">'+item.choices.map(function(c,i){return '<label class="evx-choice"><input type="radio" name="evx-answer" value="'+i+'"><span class="evx-letter" aria-hidden="true">'+String.fromCharCode(65+i)+'</span><span>'+c.text+'</span></label>';}).join('')+'</div></fieldset><details class="evx-hint"><summary>给我一条线索（不扣分）</summary><p>'+q.hint+'</p></details><button class="evx-primary evx-submit" type="submit" disabled>确认判断</button></form><div class="evx-feedback" aria-live="polite" aria-atomic="true"></div>'+sources+'</section>';if(index>0)container.querySelector('.evx-title').focus(); }
    function submit(event){event.preventDefault();if(locked||finished||disposed||selected===null)return;locked=true;var item=round[index],correct=item.choices[selected].correct;if(correct)score++;answers.push({q:item.q,correct:correct,selected:item.choices[selected].text});container.querySelector('.evx-submit').disabled=true;Array.prototype.forEach.call(container.querySelectorAll('input[type=radio]'),function(input){input.disabled=true;var choice=item.choices[Number(input.value)];input.closest('label').classList.toggle('evx-correct',choice.correct);input.closest('label').classList.toggle('evx-wrong',input.checked&&!choice.correct);});var right=item.choices.filter(function(c){return c.correct;})[0].text;container.querySelector('.evx-feedback').innerHTML='<div class="evx-explanation"><strong>'+(correct?'判断成立 +1':'这条线索值得再想想')+'</strong>'+(correct?'':'<p class="evx-answer">更有依据的判断：'+right+'</p>')+'<p>'+item.q.explain+'</p><button type="button" class="evx-primary evx-next">'+(index===5?'查看侦探报告':'下一案 →')+'</button></div>';container.querySelector('.evx-next').focus();}
    function finish(){if(finished||disposed)return;finished=true;container.innerHTML='<section class="evx-game evx-result" aria-label="证据侦探结果"><span class="evx-eyebrow">CASE CLOSED</span><h2 tabindex="-1">本轮侦探报告</h2><p class="evx-score">'+score+'<span> / 6</span></p><p>'+(score===6?'六案全部判断成立。继续保持对证据边界的敏感。':score>=4?'你已抓住多数关键线索。回看几处推理边界，判断会更稳。':'每次修正判断，都是在练习科学思考。带着解析再挑战一轮。')+'</p><span class="evx-badge">本轮徽章 · 证据侦探</span><ol class="evx-review">'+answers.map(function(a){return '<li><details><summary><span class="evx-status">'+(a.correct?'✓ 正确':'↻ 复盘')+'</span> '+a.q.title+'</summary><p>你的判断：'+a.selected+'</p><p>参考判断：'+a.q.choices[0]+'</p><p>'+a.q.explain+'</p></details></li>';}).join('')+'</ol><button type="button" class="evx-primary evx-replay">再探 6 案</button><p class="evx-small">题库共 12 案；新一轮重新抽题，可能遇到旧案。提示不扣分，每案计 1 分。</p>'+sources+'</section>';container.querySelector('h2').focus();if(typeof options.onComplete==='function')options.onComplete({game:'evidence',score:score,maxScore:6,badge:'证据侦探'});}
    function change(e){if(locked||finished||disposed||!e.target.matches('input[name="evx-answer"]'))return;selected=Number(e.target.value);container.querySelector('.evx-submit').disabled=false;}
    function click(e){if(disposed)return;if(e.target.closest('.evx-next')&&locked&&!finished){if(index===5)finish();else{index++;render();}}else if(e.target.closest('.evx-replay')&&finished)start();}
    container.addEventListener('submit',submit);container.addEventListener('change',change);container.addEventListener('click',click);start();
    return function(){disposed=true;container.removeEventListener('submit',submit);container.removeEventListener('change',change);container.removeEventListener('click',click);container.classList.remove('evx-host');container.innerHTML='';};
  }};
})();
